import{$,status,download,canvasBlob,bytes}from'./common.js';
const canvas=$('#preview'),ctx=canvas.getContext('2d');let image=null,crop=null,originalBytes=0,exportBlob=null,revision=0;
function sample(){const c=document.createElement('canvas');c.width=1200;c.height=800;const g=c.getContext('2d');const sky=g.createLinearGradient(0,0,0,800);sky.addColorStop(0,'#f5dfc5');sky.addColorStop(.5,'#d5b1bd');sky.addColorStop(1,'#718d8d');g.fillStyle=sky;g.fillRect(0,0,1200,800);g.fillStyle='#ffe7b7';g.beginPath();g.arc(880,210,86,0,Math.PI*2);g.fill();for(const [color,y,peaks]of[['#9894aa',400,[0,480,220,200,440,390,650,170,900,390,1050,260,1200,390]],['#677e85',540,[0,610,270,400,530,570,780,340,1200,580]],['#355961',730,[0,730,250,650,420,690,800,580,1200,710]]]){g.fillStyle=color;g.beginPath();g.moveTo(0,800);for(let i=0;i<peaks.length;i+=2)g.lineTo(peaks[i],peaks[i+1]);g.lineTo(1200,800);g.fill()}g.fillStyle='#edf0da';g.font='48px Georgia';g.fillText('A change of perspective.',70,730);image=c;originalBytes=0;reset();status('Sample loaded. Drag a selection to find your crop.')}
function reset(){crop={x:0,y:0,w:image.width,h:image.height};$('#width').value=Math.min(image.width,1200);$('#ratio').value='free';render()}
function render(){if(!image)return;canvas.width=image.width;canvas.height=image.height;ctx.drawImage(image,0,0);ctx.fillStyle='#0b152955';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.save();ctx.beginPath();ctx.rect(crop.x,crop.y,crop.w,crop.h);ctx.clip();ctx.drawImage(image,0,0);ctx.restore();ctx.strokeStyle='#fff';ctx.lineWidth=Math.max(2,image.width/350);ctx.strokeRect(crop.x,crop.y,crop.w,crop.h);ctx.strokeStyle='#ffffff60';for(let i=1;i<3;i++){ctx.beginPath();ctx.moveTo(crop.x+crop.w*i/3,crop.y);ctx.lineTo(crop.x+crop.w*i/3,crop.y+crop.h);ctx.moveTo(crop.x,crop.y+crop.h*i/3);ctx.lineTo(crop.x+crop.w,crop.y+crop.h*i/3);ctx.stroke()}$('#selection').textContent=Math.round(crop.w)+' × '+Math.round(crop.h);$('#original').textContent=originalBytes?bytes(originalBytes):'1200 × 800';updateEstimate()}
async function output(){if(!image)throw Error('Choose an image first.');const width=Math.round(Number($('#width').value));if(!Number.isFinite(width)||width<16||width>4096)throw Error('Choose an output width between 16 and 4096 pixels.');const c=document.createElement('canvas');c.width=width;c.height=Math.max(1,Math.round(width*crop.h/crop.w));if(c.width*c.height>20000000)throw Error('This crop is too tall for the chosen export size. Reduce the width.');const g=c.getContext('2d');if($('#format').value==='image/jpeg'){g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height)}g.drawImage(image,crop.x,crop.y,crop.w,crop.h,0,0,c.width,c.height);return canvasBlob(c,$('#format').value,Number($('#quality').value)/100)}
async function updateEstimate(){const r=++revision;try{const b=await output();if(r!==revision)return;exportBlob=b;$('#estimate').textContent=bytes(b.size);$('#export').disabled=false}catch(e){if(r===revision){$('#estimate').textContent='—';$('#export').disabled=true;status(e.message,true)}}}
async function load(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){status('Choose a JPEG, PNG or WebP image.',true);return}if(file.size>40*1048576){status('Choose an image under 40 MB.',true);return}try{const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>40000000){bitmap.close();throw Error('Choose an image below 40 megapixels.')}image=bitmap;originalBytes=file.size;reset();status('Image loaded. Drag on the preview to select your crop.')}catch(e){status(e.message||'Could not read this image.',true)}}
$('#file').onchange=e=>load(e.target.files[0]);$('#sample').onclick=sample;$('#reset').onclick=reset;$('#rotate').onclick=()=>{const c=document.createElement('canvas');c.width=image.height;c.height=image.width;const g=c.getContext('2d');g.translate(c.width,0);g.rotate(Math.PI/2);g.drawImage(image,0,0);image=c;reset()};$('#ratio').onchange=()=>{const ratio=Number($('#ratio').value);if(!ratio){reset();return}const w=Math.min(image.width,image.height*ratio);crop={x:(image.width-w)/2,y:(image.height-w/ratio)/2,w,h:w/ratio};render()};for(const id of ['width','format','quality'])$('#'+id).oninput=()=>{$('#qualityValue').textContent=$('#quality').value+'%';updateEstimate()};$('#export').onclick=async()=>{try{const b=await output();download(b,'image-studio.'+({'image/png':'png','image/webp':'webp','image/jpeg':'jpg'}[$('#format').value]));status('Your image is ready.')}catch(e){status(e.message,true)}};
let start=null;function point(e){const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(image.width,(e.clientX-r.left)/r.width*image.width)),y:Math.max(0,Math.min(image.height,(e.clientY-r.top)/r.height*image.height))}}canvas.style.touchAction='none';canvas.onpointerdown=e=>{start=point(e);canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!start)return;const p=point(e);let w=Math.abs(p.x-start.x),h=Math.abs(p.y-start.y);const ratio=Number($('#ratio').value);if(ratio){h=w/ratio;const maxH=p.y>=start.y?image.height-start.y:start.y;h=Math.min(h,maxH);w=h*ratio}if(w<2||h<2)return;crop={x:p.x>=start.x?start.x:start.x-w,y:p.y>=start.y?start.y:start.y-h,w,h};render()};canvas.onpointerup=canvas.onpointercancel=()=>{start=null};const drop=$('.drop');drop.ondragover=e=>{e.preventDefault()};drop.ondrop=e=>{e.preventDefault();load(e.dataTransfer.files[0])};sample();
